// One place that says what this collection covers. Every node downstream reads the list
// from here rather than carrying its own copy, so the scope cannot drift between sources.
const hospitals = [
  {
    "name": "ALTA BATES SUMMIT MEDICAL CENTER ALTA BATES CAMPUS",
    "state": "CA",
    "domain": "www.sutterhealth.org"
  },
  {
    "name": "BAYLOR SCOTT & WHITE ALL SAINTS MEDICAL CENTER - FORT WORTH",
    "state": "TX",
    "domain": "www.bswhealth.com"
  },
  {
    "name": "Community Hospital of Stokes",
    "state": "NC",
    "domain": "www.novanthealth.org"
  },
  {
    "name": "Doylestown Hospital",
    "state": "PA",
    "domain": "www.pennmedicine.org"
  },
  {
    "name": "Inova Alexandria Hospital",
    "state": "VA",
    "domain": "www.inova.org"
  },
  {
    "name": "Jefferson Abington Hospital",
    "state": "PA",
    "domain": "www.jeffersonhealth.org"
  },
  {
    "name": "Leonard J. Chabert Medical Center",
    "state": "LA",
    "domain": "www.ochsner.org"
  },
  {
    "name": "Scripps Green Hospital",
    "state": "CA",
    "domain": "www.scripps.org"
  },
  {
    "name": "Sharp Chula Vista Medical Center",
    "state": "CA",
    "domain": "www.sharp.com"
  }
];

const codes = ["12001", "20610", "36415", "70450", "70486", "71046", "72148", "74177", "76700", "80048", "80053", "80061", "81001", "83036", "84443", "85025", "85027", "93010", "96365", "96374", "99281", "99282", "99283", "99284", "99285", "G0378", "G0379", "J1200", "J1885", "J2405", "J7030"];

// A plain ?size=5000 on this dataset returns the first 5,000 codes ALPHABETICALLY, which
// is almost none of the ones we want - the filter has to be server-side. CMS uses the
// Drupal-style IN condition for that.
const qs = ['filter[c][condition][path]=HCPCS_Cd',
            'filter[c][condition][operator]=IN'];
codes.forEach((c, i) => qs.push(`filter[c][condition][value][${i}]=${c}`));
qs.push('filter[g][condition][path]=Rndrng_Prvdr_Geo_Lvl',
        'filter[g][condition][operator]==',
        'filter[g][condition][value]=National',
        'size=500');

return [{ json: {
  hospitals,
  codes,
  pfsUrl: 'https://data.cms.gov/data-api/v1/dataset/6fea9d79-0129-4e4c-b1b8-23cd86a4f435/data?' + qs.join('&'),
  collected_date: new Date().toISOString().slice(0, 10),
}}];

// Source 3. 45 CFR 180 requires every US hospital to host cms-hpt.txt at its web root
// containing a direct link to its machine-readable price file - so the location of a
// hospital's own prices is discoverable programmatically rather than by hand.
const scope = $('Scope').first().json;
return scope.hospitals.map(h => ({
  json: { ...h, url: `https://${h.domain}/cms-hpt.txt` }
}));

// Join the three sources into one row per hospital per code, then check the result
// before letting it out.
const scope = $('Scope').first().json;
const today = scope.collected_date;
const warnings = [];

const norm = s => String(s || '').toUpperCase().replace(/[^A-Z0-9 ]+/g, ' ')
                                 .replace(/\s+/g, ' ').trim();
const stripCity = s => String(s || '').split(/\s+-\s+/)[0];

// ---- source 1: CMS enforcement actions, all of them ------------------------
// A3's node read ?size=5000 with no offset loop and therefore saw 5,000 of 13,355. This
// one paginates; if it comes back short, that is said out loud rather than absorbed.
const actions = $('CMS enforcement actions').all().map(i => i.json)
                  .filter(a => a && a.Hosp_Name);
if (!actions.length) warnings.push('enforcement source returned nothing');
else if (actions.length < 10000) warnings.push(`only ${actions.length} enforcement actions`);

// ---- source 2: the national fee schedule -----------------------------------
const pfs = $('Medicare fee schedule').all().map(i => i.json).filter(r => r && r.HCPCS_Cd);
if (!pfs.length) warnings.push('fee schedule returned nothing');
const medicare = {};
for (const r of pfs) {
  // One row per place of service. Keep the busier one rather than whichever arrived last.
  const code = String(r.HCPCS_Cd).trim();
  const volume = parseInt(r.Tot_Srvcs || '0', 10);
  if (!medicare[code] || volume > medicare[code].volume) {
    medicare[code] = { volume,
      payment: parseFloat(r.Avg_Mdcr_Pymt_Amt),
      submitted: parseFloat(r.Avg_Sbmtd_Chrg),
      description: r.HCPCS_Desc || '' };
  }
}

// ---- source 3: each hospital's published price file ------------------------
// A failed fetch is one blank cell, not a dead run: the node is set to continue on error,
// so a hospital that is slow or down costs that hospital's URL and nothing else.
const asked = $('Price-file discovery URLs').all().map(i => i.json);
const got = $('Fetch cms-hpt.txt').all().map(i => i.json);

// Sutter serves this file as UTF-16 with a byte-order mark, so decoded as text it arrives
// as "h t t p s" with NULs between the letters and every pattern misses. Strip them.
const readable = s => String(s || '').replace(/\u0000/g, '').replace(/^﻿/, '');

// A system's file lists every hospital it operates, one block per location. Taking the
// first mrf-url in the file hands Alta Bates the price file for Sutter North Valley.
// Blocks are keyed by location-name and matched to the hospital we are actually asking
// about; the first URL is a fallback, and the row says which happened.
function priceFileFor(text, hospitalName) {
  const body = readable(text);
  const wanted = norm(hospitalName);
  const blocks = body.split(/location-name\s*:/i).slice(1);
  const urlIn = b => (b.match(/mrf-url\s*:\s*(\S+)/i) || [])[1] ||
                     (b.match(/https?:\/\/\S+?\.(?:csv|json|xml)\b/i) || [])[0] || '';

  let best = null;
  for (const b of blocks) {
    const name = norm((b.split(/\r?\n/)[0] || ''));
    const url = urlIn(b);
    if (!url) continue;
    const overlap = name.split(' ').filter(w => w.length > 3 && wanted.includes(w)).length;
    if (!best || overlap > best.overlap) best = { url, overlap, name };
  }
  if (best && best.overlap > 0) return { url: best.url, how: 'location-name match' };
  if (best) return { url: best.url, how: 'first file in the system list' };
  const any = (body.match(/https?:\/\/\S+?\.(?:csv|json|xml)\b/i) || [])[0] || '';
  return { url: any, how: any ? 'bare url in file' : '' };
}

const discovery = {};
asked.forEach((h, i) => {
  const res = got[i] || {};
  const found = priceFileFor(typeof res.body === 'string' ? res.body : res.data, h.name);
  if (!found.url) warnings.push(`no price file found for ${h.name}`);
  discovery[h.name] = {
    mrf_source_url: found.url,
    mrf_match: found.how,
    discovery_file: h.url,
    http_status: res.statusCode || '',
    last_modified: (res.headers || {})['last-modified'] || '',
  };
});

// ---- matching a hospital to its enforcement record -------------------------
// Name and state alone missed two of these nine: "... MEDICAL CENTER - FORT WORTH" is
// listed by CMS without the city, and "Community Hospital of Stokes" is listed as
// "LIFEBRITE COMMUNITY HOSPITAL OF STOKES". Both misses were recorded as a count of zero,
// which reads as a clean record and is not one. Three strategies, and the row says which
// one answered - a zero from 'none' means NOT FOUND, never NOTHING HAPPENED.
function enforcementFor(name, state) {
  const inState = actions.filter(a => norm(a.State) === norm(state));
  const pick = (rows, method) => ({ rows, method });

  let hit = inState.filter(a => norm(a.Hosp_Name) === norm(name));
  if (hit.length) return pick(hit, 'name+state');

  const trimmed = norm(stripCity(name));
  hit = inState.filter(a => norm(a.Hosp_Name) === trimmed);
  if (hit.length) return pick(hit, 'name-without-city+state');

  hit = inState.filter(a => norm(a.Hosp_Name).includes(trimmed) ||
                            trimmed.includes(norm(a.Hosp_Name)));
  const distinct = new Set(hit.map(a => norm(a.Hosp_Name)));
  if (hit.length && distinct.size === 1) return pick(hit, 'name-contained+state');

  return pick([], actions.length ? 'none' : 'source-unavailable');
}

// ---- the rows ---------------------------------------------------------------
const rows = [];
const seen = new Set();
for (const h of scope.hospitals) {
  const e = enforcementFor(h.name, h.state);
  const byDate = e.rows.slice().sort((a, b) =>
    String(a.Date_of_Action).localeCompare(String(b.Date_of_Action)));
  const latest = byDate[byDate.length - 1];
  const d = discovery[h.name] || {};

  for (const code of scope.codes) {
    const key = `${norm(h.name)}|${code}`;
    if (seen.has(key)) continue;            // duplicates removed, by construction
    seen.add(key);
    const m = medicare[code];
    rows.push({
      record_id: String(rows.length + 1).padStart(4, '0'),
      collected_date: today,
      hospital_name: h.name,
      hospital_state: h.state,
      hospital_domain: h.domain,
      code,
      code_type: /^[A-Z]/i.test(code) ? 'HCPCS' : 'CPT',
      description: m ? m.description : '',
      medicare_avg_payment: m && isFinite(m.payment) ? m.payment.toFixed(2) : '',
      medicare_avg_submitted_charge: m && isFinite(m.submitted) ? m.submitted.toFixed(2) : '',
      cms_enforcement_actions: e.rows.length,
      cms_enforcement_match: e.method,
      cms_latest_action: latest ? latest.Action : '',
      cms_latest_action_date: latest ? latest.Date_of_Action : '',
      mrf_source_url: d.mrf_source_url || '',
      mrf_discovered: d.mrf_source_url ? 'yes' : 'no',
      mrf_match: d.mrf_match || '',
      mrf_last_modified: d.last_modified || '',
      discovery_file: d.discovery_file || '',
      discovery_http_status: d.http_status || '',
    });
  }
}

// ---- checks that catch mistakes before the file is written -----------------
// These throw. A source being slow degrades a column; a dataset that is the wrong SHAPE
// is a wrong answer, and writing it would be worse than failing here.
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const badDates = rows.filter(r => !ISO.test(r.collected_date) ||
  (r.cms_latest_action_date && !ISO.test(r.cms_latest_action_date)));
if (rows.length < 50)  throw new Error(`only ${rows.length} rows - the floor is 50`);
if (rows.length > 300) throw new Error(`${rows.length} rows - the ceiling is 300`);
if (badDates.length)   throw new Error(`${badDates.length} rows have a non-ISO date`);
if (new Set(rows.map(r => `${r.hospital_name}|${r.code}`)).size !== rows.length)
  throw new Error('duplicate hospital+code pair survived');

const ESSENTIAL = ['collected_date', 'hospital_name', 'code', 'description'];
const complete = rows.filter(r => ESSENTIAL.every(k => String(r[k] || '').trim() !== ''));
const unmatched = rows.filter(r => r.cms_enforcement_match === 'none')
                      .map(r => r.hospital_name);

console.log(`rows: ${rows.length}`);
console.log(`complete on ${ESSENTIAL.join(', ')}: ${complete.length}` +
            ` (${(100 * complete.length / rows.length).toFixed(1)}%)`);
console.log(`hospitals: ${scope.hospitals.length}  codes: ${scope.codes.length}`);
console.log(`enforcement actions read: ${actions.length}`);
console.log(`hospitals with no enforcement match: ${[...new Set(unmatched)].join(', ') || 'none'}`);
if (warnings.length) console.log('warnings: ' + warnings.join(' | '));

return rows.map(json => ({ json }));
